  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are you trying to minimize the number of containers used, maximize the total weight (or total units) of goods packed, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

